import re
from decimal import ROUND_HALF_EVEN, Context, Decimal, DivisionByZero, InvalidOperation, Overflow

MAX_AMOUNT = Decimal("1000000.00")
_CENT = Decimal("0.01")
_PLAIN_DECIMAL = re.compile(r"[+-]?[0-9]+(?:\.[0-9]+)?")

# Private context for exact quantization; the global decimal context is never read or changed.
_CONTEXT = Context(
    prec=100,
    rounding=ROUND_HALF_EVEN,
    traps=[InvalidOperation, DivisionByZero, Overflow],
)


def _is_whole_cents(value):
    """True when a finite, nonzero Decimal has no nonzero digit below the cent place."""
    _sign, digits, exponent = value.as_tuple()
    trailing_zeros = 0
    for digit in reversed(digits):
        if digit:
            break
        trailing_zeros += 1
    return exponent + trailing_zeros >= -2


def parse_amount(value):
    if isinstance(value, bool):
        raise ValueError("boolean is not a valid amount")
    if isinstance(value, Decimal):
        amount = value
    elif isinstance(value, int):
        amount = Decimal(value)
    elif isinstance(value, str):
        if _PLAIN_DECIMAL.fullmatch(value) is None:
            raise ValueError(f"not a plain decimal string: {value!r}")
        amount = Decimal(value)
    else:
        raise ValueError(f"unsupported amount type: {type(value).__name__}")

    if not amount.is_finite():
        raise ValueError("amount must be finite")
    if amount <= 0:
        raise ValueError("amount must be positive")
    if amount > MAX_AMOUNT:
        raise ValueError("amount must be at most 1000000.00")
    if not _is_whole_cents(amount):
        raise ValueError("amount is not exactly representable in cents")
    return _CONTEXT.quantize(amount, _CENT)


def format_amount(value):
    return format(value, ".2f")
